type SearchResult = { pharmacy: { id: string; name: string; address: string; city: string; phone?: string; verificationStatus: string; isDemo?: boolean; coordinates?: [number, number]; openingStatus?: string; openingHours?: Array<{day:number;open:string;close:string;closed:boolean}> }; medicine: { id: string; name: string; strength: string; dosageForm: string; brand?: string; genericName?: string; composition?: string; manufacturer?: string; packSize?: string; prescriptionClass: string; isDemo?: boolean }; availableQuantity?: number; displayedQuantity: string | number; freshness: string; confirmedAvailable: boolean; lastUpdatedAt: string; distanceKm?: number; price?: number; mrp?: number };
const pharmacyMarker = icon({ iconUrl: markerIcon, iconRetinaUrl: markerIconRetina, shadowUrl: markerShadow, iconSize: [25, 41], iconAnchor: [12, 41], popupAnchor: [1, -34], shadowSize: [41, 41] });
