const age = (value: string) => new Intl.DateTimeFormat('en-IN', { hour: 'numeric', minute: '2-digit', day: 'numeric', month: 'short' }).format(new Date(value));

export function HomePage() {
  const [q, setQ] = useState(''); const [results, setResults] = useState<SearchResult[]>([]); const [loading, setLoading] = useState(false); const [error, setError] = useState(''); const nav = useNavigate();
  async function search(event: FormEvent) { event.preventDefault(); if (q.trim().length < 2) return; setLoading(true); setError(''); try { const { data } = await api.get('/search', { params: { q, page: 1, limit: 3 } }); setResults(data.data.results); } catch (e) { setError(errorMessage(e)); } finally { setLoading(false); } }
  return <><section className="hero"><div className="hero-glow"/><div className="container hero-grid"><motion.div initial={{ opacity: 0, y: 15 }} animate={{ opacity: 1, y: 0 }} transition={{ duration: .45 }} className="hero-copy"><div className="eyebrow"><span className="eyebrow-dot"/> YOUR NEIGHBOURHOOD, BETTER CONNECTED</div><h1>Find your medicine.<br/><em>Before you step out.</em></h1><p className="hero-lede">See nearby pharmacies reporting availability, compare distance and freshness, and contact the pharmacy directly.</p><form className="search-box hero-search" onSubmit={search}><Search size={20}/><input aria-label="Medicine name" placeholder="Search a medicine, brand or salt" value={q} onChange={(e) => setQ(e.target.value)} /><Button disabled={loading}>{loading ? 'Searching…' : 'Search'}</Button></form><div className="hero-trust"><span><ShieldCheck size={16}/> Participating pharmacies</span><span><MapPin size={16}/> Nearby results</span><span><Clock3 size={16}/> Freshness shown</span></div></motion.div><div className="hero-visual"><div className="hero-orbit orbit-one"/><div className="hero-orbit orbit-two"/><div className="hero-cross"><span/><span/></div><div className="hero-pharmacy-card"><span className="pharmacy-icon"><Store size={21}/></span><div><b>Your neighbourhood pharmacies</b><small><span className="online-dot"/> Reporting availability</small></div><span className="distance-tag">Nearby</span></div><div className="hero-note"><span className="note-check"><Check size={15}/></span><span><b>Check before you travel</b><small>Always confirm directly with the pharmacy</small></span></div></div></div></section>
    {error && <div className="container"><div className="inline-error">{error}</div></div>}{results.length > 0 && <section className="container quick-results"><div className="section-heading"><div><div className="eyebrow">SEARCH RESULTS</div><h2>Nearby availability</h2></div><button className="text-link" onClick={() => nav(`/search?q=${encodeURIComponent(q)}`)}>View all <ArrowRight size={16}/></button></div><div className="result-grid">{results.map((r) => <ResultCard key={`${r.pharmacy.id}-${r.medicine.id}`} result={r} />)}</div></section>}
    <section className="container how-section" id="how-it-works"><div className="section-heading centered"><div><div className="eyebrow">A LITTLE LESS RUNNING AROUND</div><h2>A clearer path to your pharmacy</h2><p>MedFind helps you discover and contact participating pharmacies near you.</p></div></div><div className="steps-grid">{[{n:'01',title:'Search your medicine',text:'Look up a brand, generic name or composition.'},{n:'02',title:'See nearby pharmacies',text:'Compare distance and the time inventory was last updated.'},{n:'03',title:'Confirm directly',text:'Contact the pharmacy to confirm before travelling.'}].map((s) => <Card className="step-card" key={s.n}><span className="step-number">{s.n}</span><h3>{s.title}</h3><p>{s.text}</p><ChevronRight className="step-arrow" size={18}/></Card>)}</div></section>
    <section className="values-section" id="for-pharmacies"><div className="container values-grid"><div><div className="eyebrow">BUILT AROUND TRUST</div><h2>Availability should be clear.<br/><em>And easy to verify.</em></h2><p>Pharmacies report their own inventory. MedFind shows when it was last updated, so you can decide whether to call ahead.</p><Link className="button button-outline" to="/about">Learn about MedFind <ArrowRight size={16}/></Link></div><div className="trust-points"><div><ShieldCheck/><span><b>Verified pharmacy profiles</b><small>Public discovery is limited to approved pharmacies.</small></span></div><div><Clock3/><span><b>Inventory freshness labels</b><small>Older stock information is clearly flagged.</small></span></div><div><Stethoscope/><span><b>Pharmacy-led decisions</b><small>Dispensing and prescription decisions stay with pharmacy professionals.</small></span></div></div></div></section>
    <section className="container cta-section"><div className="cta-card"><div><div className="eyebrow">JOIN YOUR LOCAL NETWORK</div><h2>Make medicine discovery easier.</h2><p>Customers can find nearby participating pharmacies. Pharmacy teams can keep availability up to date.</p></div><Link className="button" to="/register">Get started <ArrowRight size={16}/></Link></div></section></>;
}

export function SearchPage() {
  const { user, loading: authLoading } = useAuth();
  const [savedLocations, setSavedLocations] = useState<SavedLocation[]>([]); const [selectedLocation, setSelectedLocation] = useState('');
  const [preferencesFor, setPreferencesFor] = useState(''); const [settingsError, setSettingsError] = useState('');
  const locationChoiceVersion = useRef(0);
  const appliedPinCode = useRef<string | undefined>();
  const location = useLocation(); const initial = new URLSearchParams(location.search).get('q') || '';
  const exactId = new URLSearchParams(location.search).get('medicineId');
  const [exactLoading, setExactLoading] = useState(Boolean(exactId)); const [exactError, setExactError] = useState('');
  const [q, setQ] = useState(initial); const [selectedMedicine, setSelectedMedicine] = useState<MedicineSuggestion | null>(null);
  const [pinCode, setPinCode] = useState(''); const [submitted, setSubmitted] = useState<{ q: string; medicineId?: string; pinCode?: string } | null>(!exactId && initial.trim().length >= 2 ? { q: initial.trim() } : null);
  const [results, setResults] = useState<SearchResult[]>([]); const [total, setTotal] = useState(0); const [coverageLimited, setCoverageLimited] = useState(false); const [notices, setNotices] = useState<string[]>([]);
  const [loading, setLoading] = useState(false); const [error, setError] = useState(''); const [position, setPosition] = useState<[number, number] | null>(null);
  const [radius, setRadius] = useState(10); const [sort, setSort] = useState('distance'); const [availability, setAvailability] = useState('all'); const [freshness, setFreshness] = useState('all'); const [map, setMap] = useState(false); const [page, setPage] = useState(1);
  const pageSize = 12;
  const locationReady = !authLoading && preferencesFor === (user?.id || 'guest');
  useEffect(() => {
    const controller = new AbortController(); const parameters = new URLSearchParams(location.search); const id = parameters.get('medicineId'); const query = parameters.get('q') || '';
    setPage(1); setExactError(''); setSelectedMedicine(null); setQ(query); setResults([]); setTotal(0); setCoverageLimited(false); setNotices([]);
    if (!id) { setExactLoading(false); setSubmitted(query.trim().length >= 2 ? { q: query.trim(), pinCode: appliedPinCode.current } : null); return () => controller.abort(); }
    setSubmitted(null);
    if (!/^[0-9a-f]{24}$/i.test(id)) { setExactLoading(false); setExactError('This catalogue selection is invalid. Enter a medicine name to start another search.'); return () => controller.abort(); }
    setExactLoading(true);
    void catalogue.publicMedicine(id, controller.signal).then((medicine) => {
      if (controller.signal.aborted) return;
      setQ(medicine.name); setSelectedMedicine({ ...medicine, matchType: 'partial' }); setSubmitted({ q: medicine.name, medicineId: medicine._id, pinCode: appliedPinCode.current });
    }).catch((reason) => { if (!controller.signal.aborted) setExactError(`${errorMessage(reason)}. Enter a medicine name to start another search.`); })
      .finally(() => { if (!controller.signal.aborted) setExactLoading(false); });
    return () => controller.abort();
  }, [location.search]);
  function applySavedLocation(entry?: SavedLocation) {
    locationChoiceVersion.current++;
    appliedPinCode.current = entry?.pinCode || undefined;
    setSelectedLocation(entry?.id || ''); setPosition(entry?.latitude !== undefined && entry.longitude !== undefined ? [entry.latitude, entry.longitude] : null);
    setPinCode(entry?.pinCode || ''); setPage(1); setSubmitted((current) => current ? { ...current, pinCode: entry?.pinCode || undefined } : current);
  }
  useEffect(() => {
    if (authLoading) return;
    const controller = new AbortController(); setSettingsError(''); setSavedLocations([]); applySavedLocation(); setRadius(10); setMap(false);
    if (!user) { setPreferencesFor('guest'); return () => { controller.abort(); locationChoiceVersion.current++; }; }
    const userId = user.id;
    void customerSettings.get(controller.signal).then((settings) => {
      if (controller.signal.aborted) return;
      setSavedLocations(settings.locations); setRadius(settings.preferences.searchRadiusKm); setMap(settings.preferences.searchView === 'map');
      applySavedLocation(settings.locations.find((entry) => entry.isDefault));
    }).catch((reason) => { if (!controller.signal.aborted) setSettingsError(`Saved settings could not be loaded: ${errorMessage(reason)}. You can choose a location below.`); })
      .finally(() => { if (!controller.signal.aborted) setPreferencesFor(userId); });
    return () => { controller.abort(); locationChoiceVersion.current++; };
  }, [user?.id, authLoading]);
  function submit(event: FormEvent) {
    event.preventDefault(); const query = q.trim();
    if (query.length < 2) { setError('Enter at least two characters to search.'); return; }
    if (!selectedMedicine && query.split(/\s+/).length > 8) { setError('Use at most eight search terms.'); return; }
    if (pinCode && !/^[0-9]{6}$/.test(pinCode)) { setError('Enter a valid six-digit PIN code.'); return; }
    setError(''); setPage(1); if (!selectedMedicine && sort === 'price') setSort('distance');
    appliedPinCode.current = pinCode || undefined;
    if (pinCode && !selectedLocation) { locationChoiceVersion.current++; setPosition(null); }
    setSubmitted({ q: query, ...(selectedMedicine ? { medicineId: selectedMedicine._id } : {}), ...(pinCode ? { pinCode } : {}) });
  }
  useEffect(() => {
    if (!submitted || !locationReady || exactLoading || exactError) { setLoading(false); return; }
    const controller = new AbortController(); setLoading(true); setError('');
    void api.get('/search', { signal: controller.signal, params: { ...submitted, page, limit: pageSize, ...(position ? { lat: position[0], lng: position[1] } : {}), radiusKm: radius, sort, availability, freshness } }).then(({ data }) => {
      if (controller.signal.aborted) return;
      const lastPage = Math.max(1, Math.ceil(data.data.total / pageSize));
      setTotal(data.data.total); setCoverageLimited(Boolean(data.data.coverageLimited)); setNotices(data.data.notices || []);
      if (page > lastPage) { setPage(lastPage); return; }
      setResults(data.data.results);
    }).catch((e) => { if (!controller.signal.aborted) { setError(errorMessage(e)); setResults([]); setTotal(0); setCoverageLimited(false); setNotices([]); } }).finally(() => { if (!controller.signal.aborted) setLoading(false); });
    return () => controller.abort();
  }, [submitted, position, radius, sort, availability, freshness, page, locationReady, exactLoading, exactError]);
  const center: [number, number] | null = position || (results.find((item) => item.pharmacy.coordinates)?.pharmacy.coordinates?.slice().reverse() as [number, number] | undefined) || null;
  const pageCount = Math.max(1, Math.ceil(total / pageSize));
  return <section className="container page-section search-page">
    <div className="page-intro"><div className="eyebrow">MEDICINE DISCOVERY</div><h1>Find nearby availability</h1><p>Search a medicine and review pharmacy reported availability before you travel.</p></div>
    <form className="search-box large-search" onSubmit={submit}><Search size={20}/><MedicineAutocomplete disabled={exactLoading} value={q} selectedId={selectedMedicine?._id} onChange={(value) => { setExactError(''); setQ(value); setSelectedMedicine(null); }} onSelect={(medicine) => { setQ(medicine.name); setSelectedMedicine(medicine); }}/><Button disabled={loading || !locationReady || exactLoading}>{loading ? 'Searching...' : 'Search'}</Button></form>
    {selectedMedicine && <p className="search-selection">Selected: {selectedMedicine.name}{selectedMedicine.isDemo ? ' - DEMO' : ''} - {selectedMedicine.strength} - {selectedMedicine.dosageForm}{selectedMedicine.packSize ? ` - ${selectedMedicine.packSize}` : ''}. Check the details before requesting.</p>}
    {exactError && <div className="inline-error" role="alert">{exactError}</div>}{settingsError && <p className="search-hint" role="status">{settingsError}</p>}
    {user && <div className="manual-location-row"><label htmlFor="search-saved-location">Saved location</label><select id="search-saved-location" disabled={!locationReady} value={selectedLocation} onChange={(event) => applySavedLocation(savedLocations.find((entry) => entry.id === event.target.value))}><option value="">Choose a location</option>{savedLocations.map((entry) => <option key={entry.id} value={entry.id}>{entry.label}{entry.isDefault ? ' (default)' : ''}</option>)}</select><Link to="/profile">Manage saved locations</Link></div>}
    <div className="manual-location-row"><MapPin size={15}/><label htmlFor="search-pincode">PIN code</label><input id="search-pincode" disabled={!locationReady} inputMode="numeric" maxLength={6} placeholder="6-digit PIN" value={pinCode} onChange={(e) => { locationChoiceVersion.current++; setSelectedLocation(''); setPinCode(e.target.value.replace(/[^0-9]/g, '').slice(0, 6)); }}/><span>Press Search to apply the PIN. Location permission is optional.</span></div>
    <div className="filter-row">
      <button type="button" disabled={!locationReady} className={`filter-button ${position ? 'filter-active' : ''}`} onClick={() => { if (!navigator.geolocation) { setError('Geolocation is not supported by this browser.'); return; } const request = ++locationChoiceVersion.current; navigator.geolocation.getCurrentPosition((p) => { if (request !== locationChoiceVersion.current) return; applySavedLocation(); setError(''); setPosition([p.coords.latitude, p.coords.longitude]); }, () => { if (request === locationChoiceVersion.current) setError('Location was not shared. You can still search by medicine or PIN.'); }, { timeout: 10000 }); }}>{position ? 'Update my location' : 'Use my location'}</button>
      {position && <button type="button" className="filter-button" onClick={() => applySavedLocation()}>Clear location</button>}
      <label className="filter-select">Radius <select value={radius} disabled={!position || !locationReady} onChange={(e) => { setPage(1); setRadius(Number(e.target.value)); }}>{![5, 10, 20, 50].includes(radius) && <option value={radius}>{radius} km</option>}<option value="5">5 km</option><option value="10">10 km</option><option value="20">20 km</option><option value="50">50 km</option></select></label>
      <label className="filter-select">Sort by <select value={sort} onChange={(e) => { setPage(1); setSort(e.target.value); }}><option value="distance">Distance</option><option value="freshness">Recently updated</option><option value="price" disabled={!submitted?.medicineId}>Price (select a medicine)</option></select></label>
      <label className="filter-select">Availability <select value={availability} onChange={(e) => { setPage(1); setAvailability(e.target.value); }}><option value="all">All reported stock</option><option value="reservable">Eligible to request</option></select></label>
      <label className="filter-select">Freshness <select value={freshness} onChange={(e) => { setPage(1); setFreshness(e.target.value); }}><option value="all">All updates</option><option value="RECENTLY_UPDATED">Recently updated</option><option value="NEEDS_CONFIRMATION">Needs confirmation</option><option value="STALE_WARNING">Stale warning</option><option value="UNAVAILABLE_FOR_CONFIRMED_SEARCH">Older reports</option></select></label>
      <button type="button" disabled={!locationReady} className={`view-toggle ${map ? 'filter-active' : ''}`} onClick={() => setMap(!map)}><MapPin size={15}/>{map ? 'List view' : 'Map view'}</button><span className="filter-spacer"/><span className="result-count" aria-live="polite">{submitted ? `${coverageLimited ? 'At least ' : ''}${total} matches` : ''}</span>
    </div>
    {submitted && <p className="search-hint">Showing results for: {submitted.q}{submitted.pinCode ? ` - PIN ${submitted.pinCode}` : ''}</p>}
    {!position && <p className="search-hint">Distance and radius require coordinates from a saved location or your browser. Without one, distance is unavailable.</p>}
    {notices.map((notice) => <p className="search-hint" key={notice}>{notice}</p>)}{error && <div className="inline-error" role="alert">{error}</div>}
    {loading || !locationReady || exactLoading ? <Loading/> : results.length ? <><div className={map && center ? 'search-map-layout' : ''}>{map && center && <div className="map-panel"><MapContainer key={`${center.join(',')}-${page}`} center={center} zoom={12} scrollWheelZoom={false} style={{ height: '100%', minHeight: 460 }}><TileLayer attribution='&copy; <a href="https://www.openstreetmap.org/copyright">OpenStreetMap</a>' url={import.meta.env.VITE_MAP_TILE_URL || 'https://{s}.tile.openstreetmap.org/{z}/{x}/{y}.png'}/>{results.filter((r) => r.pharmacy.coordinates).map((r) => <Marker icon={pharmacyMarker} key={`${r.pharmacy.id}-${r.medicine.id}`} position={r.pharmacy.coordinates!.slice().reverse() as [number,number]}><Popup>{r.pharmacy.name}<br/>{r.medicine.name}</Popup></Marker>)}</MapContainer></div>}<div className="result-list">{results.map((r, index) => <motion.div key={`${r.pharmacy.id}-${r.medicine.id}`} initial={{ opacity: 0, y: 8 }} animate={{ opacity: 1, y: 0 }} transition={{ delay: index * .025 }}><ResultCard result={r}/></motion.div>)}</div></div><div className="search-pagination"><Button type="button" className="button-outline" disabled={page <= 1} onClick={() => setPage((value) => value - 1)}>Previous</Button><span>Page {page} of {pageCount}</span><Button type="button" className="button-outline" disabled={page >= pageCount} onClick={() => setPage((value) => value + 1)}>Next</Button></div></> : submitted && !error ? <Card className="empty-state"><span className="empty-icon"><Search/></span><h3>No availability found</h3><p>Try a different spelling, choose a suggestion, or adjust the location and filters. Confirm details with the pharmacy.</p></Card> : !error && <Card className="search-guidance"><span className="guidance-icon"><Search/></span><h3>What medicine are you looking for?</h3><p>Search by brand, generic name, composition, strength or form.</p></Card>}
  </section>;
}

const weekdays = ['Sunday', 'Monday', 'Tuesday', 'Wednesday', 'Thursday', 'Friday', 'Saturday'];
function listedHours(hours: SearchResult['pharmacy']['openingHours']): string {
  if (!hours?.length) return 'Hours not provided';
  const parts = new Intl.DateTimeFormat('en-US', { timeZone: 'Asia/Kolkata', weekday: 'short', hour: '2-digit', minute: '2-digit', hourCycle: 'h23' }).formatToParts(new Date());
  const weekday = parts.find((part) => part.type === 'weekday')?.value;
  const day = ['Sun', 'Mon', 'Tue', 'Wed', 'Thu', 'Fri', 'Sat'].indexOf(weekday || '');
  const current = hours.find((entry) => entry.day === day); if (!current) return 'Hours not provided for today';
  if (current.closed) return 'Listed closed today';
  if (!/^\d{2}:\d{2}$/.test(current.open || '') || !/^\d{2}:\d{2}$/.test(current.close || '') || current.close <= current.open) return 'Hours need confirmation';
  const time = `${parts.find((part) => part.type === 'hour')?.value}:${parts.find((part) => part.type === 'minute')?.value}`;
  return time >= current.open && time < current.close ? `Listed open until ${current.close} IST` : `Listed closed - today ${current.open} to ${current.close} IST`;
}
function ResultCard({ result }: { result: SearchResult }) {
  const { user } = useAuth(); const [message, setMessage] = useState(''); const [busy, setBusy] = useState(false); const [saved, setSaved] = useState(false); const [quantity, setQuantity] = useState('1'); const requestKey = useRef<string | null>(null);
  const demo = Boolean(result.pharmacy.isDemo || result.medicine.isDemo);
  async function savePharmacy() { if (!user?.roles.includes('CUSTOMER')) { setMessage('Log in with a customer account to save pharmacies.'); return; } try { await api.post('/saved-pharmacies', { pharmacyId: result.pharmacy.id }); setSaved(true); setMessage('Pharmacy saved to your account.'); } catch (e) { setMessage(errorMessage(e)); } }
  async function reserve() {
    if (!user) { setMessage('Log in as a customer to request a reservation.'); return; }
    if (!user.roles.includes('CUSTOMER')) { setMessage('Reservations are available to customer accounts.'); return; }
    const requested = Number(quantity); if (!Number.isInteger(requested) || requested < 1 || requested > 100 || (result.availableQuantity !== undefined && requested > result.availableQuantity)) { setMessage('Enter a whole quantity within the reported stock, up to 100.'); return; }
    setBusy(true); setMessage(''); requestKey.current ||= crypto.randomUUID();
    try { await api.post('/reservations', { pharmacyId: result.pharmacy.id, medicineId: result.medicine.id, quantity: requested }, { headers: { 'Idempotency-Key': requestKey.current } }); requestKey.current = null; setMessage('Request sent. The pharmacy will confirm availability.'); }
    catch (e) { setMessage(errorMessage(e)); } finally { setBusy(false); }
  }
  return <Card className="result-card">
    <div className="result-top"><span className="medicine-mark"><Crosshair size={18}/></span>{demo ? <StatusPill tone="warn">DEMO DATA - NOT LIVE STOCK</StatusPill> : <StatusPill tone={result.confirmedAvailable ? 'good' : 'warn'}>{result.freshness.replaceAll('_', ' ').toLowerCase()}</StatusPill>}</div>
    <h3><Link to={`/medicines/${result.medicine.id}`}>{result.medicine.name}</Link></h3><p className="medicine-sub">{[result.medicine.brand, result.medicine.strength, result.medicine.dosageForm, result.medicine.packSize].filter(Boolean).join(' - ')}</p>
    <div className="result-classification">Prescription class: {result.medicine.prescriptionClass === 'UNVERIFIED' ? 'unverified - ask the pharmacy' : result.medicine.prescriptionClass.replaceAll('_',' ').toLowerCase()}</div>
    <details className="medicine-extra"><summary>Medicine details</summary><dl>{result.medicine.genericName && <><dt>Generic name</dt><dd>{result.medicine.genericName}</dd></>}{result.medicine.composition && <><dt>Composition</dt><dd>{result.medicine.composition}</dd></>}{result.medicine.manufacturer && <><dt>Manufacturer</dt><dd>{result.medicine.manufacturer}</dd></>}</dl><small>Confirm the exact product and any prescription requirements with the pharmacy.</small></details>
    <div className="result-divider"/><div className="pharmacy-result"><span className="pharmacy-small-icon"><Store size={16}/></span><span><b>{result.pharmacy.name}</b><small>{result.pharmacy.address}, {result.pharmacy.city}</small></span>{!demo && <StatusPill tone="good">Verified</StatusPill>}{user?.roles.includes('CUSTOMER') && !demo && <button className="save-pharmacy-button" aria-label="Save pharmacy" title="Save pharmacy" onClick={() => void savePharmacy()}><Bookmark size={15}/>{saved ? 'Saved' : 'Save'}</button>}</div>
    {demo && <p className="inline-feedback">Sample inventory for local demonstration only. Do not rely on it for travel or care.</p>}
    <p className="hours-summary">{result.pharmacy.openingStatus || listedHours(result.pharmacy.openingHours)} - Confirm directly before travel.</p>
    {!!result.pharmacy.openingHours?.length && <details className="medicine-extra"><summary>Weekly pharmacy hours</summary><ul className="hours-list">{[...result.pharmacy.openingHours].sort((a,b) => a.day - b.day).map((entry) => <li key={entry.day}><span>{weekdays[entry.day] || 'Day'}</span><span>{entry.closed ? 'Closed' : `${entry.open} to ${entry.close} IST`}</span></li>)}</ul></details>}
    <div className="availability-row"><div><small>{demo ? 'SAMPLE QUANTITY' : 'REPORTED STOCK'}</small><b>{demo ? 'Not real availability' : result.confirmedAvailable ? `${result.displayedQuantity} available` : 'Confirm with pharmacy'}</b></div><div className="result-price"><small>{result.medicine.packSize ? `PRICE / ${result.medicine.packSize.toUpperCase()}` : 'PRICE / PACK'}</small><b>{demo ? 'Sample only' : money(result.price)}</b>{!demo && result.mrp != null && <small>MRP {money(result.mrp)}</small>}</div></div>
    <div className="result-meta"><span>{result.distanceKm != null ? `${result.distanceKm.toFixed(1)} km away` : 'Distance unavailable'}</span><span>Updated {age(result.lastUpdatedAt)}</span></div>
    <div className="result-actions">{demo ? <button className="button button-outline" disabled>Demo pharmacy</button> : result.pharmacy.phone ? <a className="button button-outline" href={`tel:${result.pharmacy.phone}`}>Call pharmacy</a> : <button className="button button-outline" onClick={() => setMessage('Phone details are not available. Contact the pharmacy through its listed address.')}>Contact pharmacy</button>}
      {!demo && <label className="reservation-quantity">Qty <input type="number" min="1" max={Math.min(100, result.availableQuantity ?? 100)} step="1" value={quantity} onChange={(e) => { setQuantity(e.target.value); requestKey.current = null; }} aria-label={`Quantity of ${result.medicine.name}`}/></label>}
      <Button disabled={busy || !result.confirmedAvailable || demo} onClick={() => void reserve()}>{busy ? 'Sending...' : demo ? 'Demo only' : 'Request to reserve'}</Button>
    </div>
    {result.pharmacy.coordinates && !demo && <a className="directions-link" target="_blank" rel="noreferrer" href={`https://www.openstreetmap.org/directions?engine=fossgis_osrm_car&route=%3B${result.pharmacy.coordinates[1]}%2C${result.pharmacy.coordinates[0]}`}>Get directions <ArrowRight size={13}/></a>}
    {message && <p className="inline-feedback" role="status">{message}</p>}<p className="disclaimer">Reservation is a request, not a sale. Price shown is for the first available batch; the pharmacy confirms stock, total price and applicable requirements.</p>
  </Card>;
}

export function LoginPage() { const { signIn, user } = useAuth(); const nav = useNavigate(); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); if (user) return <Navigate to="/workspace" replace/>; async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { await signIn(email, password); nav('/workspace'); } catch (err) { setError(errorMessage(err)); } finally { setBusy(false); } } return <AuthFrame eyebrow="WELCOME BACK" title="Log in to MedFind" text="Sign in to manage your account and requests."><form onSubmit={submit} className="form-stack"><Field label="Email address" type="email" autoComplete="email" required value={email} onChange={(e) => setEmail(e.target.value)}/><Field label="Password" type="password" autoComplete="current-password" required value={password} onChange={(e) => setPassword(e.target.value)}/>{error && <div className="inline-error">{error}</div>}<Button disabled={busy}>{busy ? 'Signing in…' : 'Log in'}</Button><Link className="form-secondary" to="/forgot-password">Forgot password?</Link></form><p className="auth-foot">New to MedFind? <Link to="/register">Create an account</Link></p></AuthFrame>; }

export function RegisterPage() { const { user, refresh } = useAuth(); const nav = useNavigate(); const [name, setName] = useState(''); const [email, setEmail] = useState(''); const [password, setPassword] = useState(''); const [accountType, setAccountType] = useState('CUSTOMER'); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); if (user) return <Navigate to="/workspace" replace/>; async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { const response = await api.post('/auth/register', { name, email, password, accountType }); await refresh(); const token = response.data.data.developmentVerificationToken; nav(token ? `/verify-email?token=${encodeURIComponent(token)}` : '/verify-email'); } catch (err) { setError(errorMessage(err)); } finally { setBusy(false); } } return <AuthFrame eyebrow="GET STARTED" title="Create your account" text="Join a growing network making local medicine discovery easier."><form onSubmit={submit} className="form-stack"><Field label="Full name" required minLength={2} value={name} onChange={(e) => setName(e.target.value)}/><Field label="Email address" type="email" required value={email} onChange={(e) => setEmail(e.target.value)}/><Field label="Password" type="password" minLength={10} hint="Use at least 10 characters." required value={password} onChange={(e) => setPassword(e.target.value)}/><label className="field"><span>Account type</span><select value={accountType} onChange={(e) => setAccountType(e.target.value)}><option value="CUSTOMER">Customer</option><option value="PHARMACY_OWNER">Pharmacy owner</option></select></label>{error && <div className="inline-error">{error}</div>}<Button disabled={busy}>{busy ? 'Creating…' : 'Create account'}</Button></form><p className="auth-foot">Already registered? <Link to="/login">Log in</Link></p></AuthFrame>; }

function AuthFrame({ eyebrow, title, text, children }: { eyebrow: string; title: string; text: string; children: ReactNode }) { return <div className="auth-page"><div className="auth-aside"><div className="eyebrow">MEDFIND FOR EVERY NEIGHBOURHOOD</div><h2>Spend less time searching.<br/><em>More time feeling better.</em></h2><p>A clearer way to discover local pharmacies reporting medicine availability.</p><div className="auth-aside-mark"><HeartPulse size={72}/></div></div><Card className="auth-card"><div className="eyebrow">{eyebrow}</div><h1>{title}</h1><p>{text}</p>{children}</Card></div>; }

export function ForgotPasswordPage() { const [email, setEmail] = useState(''); const [done, setDone] = useState(false); const [token, setToken] = useState(''); const [error, setError] = useState(''); async function submit(e: FormEvent) { e.preventDefault(); setError(''); try { const { data } = await api.post('/auth/forgot-password', { email }); setToken(data.data.developmentResetToken || ''); setDone(true); } catch (err) { setError(errorMessage(err)); } } return <AuthFrame eyebrow="ACCOUNT RECOVERY" title="Reset your password" text="Enter your email and we’ll send reset instructions if an account matches."><form className="form-stack" onSubmit={submit}><Field label="Email address" type="email" required value={email} onChange={(e) => setEmail(e.target.value)}/>{error && <div className="inline-error">{error}</div>}{done ? <div className="inline-success">If this account exists, reset instructions will be sent.{token && <p>Local development reset link: <Link to={`/reset-password?token=${encodeURIComponent(token)}`}>Continue to reset</Link></p>}</div> : <Button>Send instructions</Button>}<Link className="form-secondary" to="/login">Back to log in</Link></form></AuthFrame>; }

export function VerifyEmailPage() {
  const location = useLocation(); const { user, refresh } = useAuth();
  const [token, setToken] = useState(() => new URLSearchParams(location.search).get('token') || '');
  const [message, setMessage] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  async function verify() {
    setBusy(true); setError('');
    try { await api.post('/auth/verify-email', { token }); setToken(''); window.history.replaceState(window.history.state, '', '/verify-email'); setMessage('Your email is verified.'); await refresh(); }
    catch (e) { setError(errorMessage(e)); } finally { setBusy(false); }
  }
  async function resend() {
    setBusy(true); setError('');
    try { const { data } = await api.post('/auth/resend-verification'); setToken(data.data.developmentVerificationToken || ''); setMessage(data.data.alreadyVerified ? 'Your email is already verified.' : data.data.developmentVerificationToken ? 'A local verification token is ready below.' : 'Check your email for a new verification link.'); }
    catch (e) { setError(errorMessage(e)); } finally { setBusy(false); }
  }
  return <AuthFrame eyebrow="ACCOUNT VERIFICATION" title="Verify your email" text="Open the link sent to your email, then confirm it here.">
    {error && <div className="inline-error" role="alert">{error}</div>}{message && <div className="inline-success" role="status">{message}</div>}
    {token && <Button type="button" disabled={busy} onClick={() => void verify()}>{busy ? 'Verifying?' : 'Confirm email'}</Button>}
    {!token && !message && <p>Check your inbox for your verification link.</p>}
    {user ? <Button type="button" className="button-outline" disabled={busy || Boolean(user.emailVerifiedAt)} onClick={() => void resend()}>Send a new link</Button> : <Link className="text-link" to="/login">Sign in to request another link</Link>}
    <Link className="form-secondary" to="/workspace">Continue to MedFind</Link>
  </AuthFrame>;
}

export function ResetPasswordPage() { const { refresh } = useAuth(); const location = useLocation(); const token = new URLSearchParams(location.search).get('token') || ''; const nav = useNavigate(); const [password, setPassword] = useState(''); const [error, setError] = useState(''); const [done, setDone] = useState(false); async function submit(e: FormEvent) { e.preventDefault(); setError(''); try { await api.post('/auth/reset-password', { token, password }); window.history.replaceState(window.history.state, '', '/reset-password'); await refresh(); setDone(true); } catch (e) { setError(errorMessage(e)); } } return <AuthFrame eyebrow="ACCOUNT RECOVERY" title="Choose a new password" text="Use at least 10 characters for your new password."><form className="form-stack" onSubmit={submit}><Field label="New password" type="password" minLength={10} required value={password} onChange={(e) => setPassword(e.target.value)}/>{error && <div className="inline-error">{error}</div>}{done ? <><div className="inline-success">Password updated. Sign in again with your new password.</div><Button type="button" onClick={() => nav('/login')}>Go to log in</Button></> : <Button disabled={!token}>Update password</Button>}</form></AuthFrame>; }

export function WorkspaceRedirect() { const { user, loading } = useAuth(); if (loading) return <Loading/>; if (!user) return <Navigate to="/login" replace/>; const role = ['SUPER_ADMIN', 'ADMIN', 'SUPPORT_ADMIN', 'PHARMACY_OWNER', 'PHARMACIST', 'PHARMACY_STAFF'].find((r) => user.roles.includes(r)); return <Navigate to={role === 'SUPER_ADMIN' || role === 'ADMIN' ? '/admin' : role === 'SUPPORT_ADMIN' ? '/support/inbox' : role === 'PHARMACIST' ? '/pharmacist' : role?.startsWith('PHARMACY') ? '/pharmacy' : '/dashboard'} replace/>; }
export function Protected({ children, roles }: { children: ReactNode; roles?: string[] }) { const { user, loading } = useAuth(); const loc = useLocation(); if (loading) return <Loading/>; if (!user) return <Navigate to="/login" state={{ from: loc.pathname }} replace/>; if (roles && !user.roles.some((role) => roles.includes(role))) return <Navigate to="/workspace" replace/>; return children; }

export function CustomerDashboard() { const { user } = useAuth(); const [reservations, setReservations] = useState<any[]>([]); const [loading, setLoading] = useState(true); useEffect(() => { api.get('/reservations').then((r) => setReservations(r.data.data.reservations)).catch(() => {}).finally(() => setLoading(false)); }, []); return <div className="container page-section"><div className="dashboard-welcome"><div><div className="eyebrow">YOUR MEDFIND</div><h1>Good to see you, {user?.name.split(' ')[0]}.</h1><p>Find local availability and keep track of your reservation requests.</p></div><Link className="button" to="/search"><Search size={16}/> Search a medicine</Link></div><div className="dashboard-grid"><Card className="dashboard-card"><div className="card-heading"><div><div className="eyebrow">YOUR ACTIVITY</div><h2>Reservation requests</h2></div><StatusPill>{reservations.length} total</StatusPill></div>{loading ? <Loading/> : reservations.length ? <div className="table-wrap"><table><thead><tr><th>Medicine</th><th>Pharmacy</th><th>Status</th><th>Requested</th><th/></tr></thead><tbody>{reservations.map((r) => <tr key={r._id}><td>{r.medicineId?.name || 'Medicine'}</td><td>{r.pharmacyId?.name || 'Pharmacy'}</td><td><StatusPill tone={r.status === 'CONFIRMED' || r.status === 'READY_FOR_PICKUP' ? 'good' : r.status === 'REJECTED' ? 'bad' : 'warn'}>{r.status?.replaceAll('_', ' ')}</StatusPill></td><td>{age(r.createdAt)}</td><td>{r.status === 'PENDING' || r.status === 'CONFIRMED' ? <button className="table-action" onClick={() => void api.patch(`/reservations/${r._id}/status`, { status: 'CANCELLED' }).then(() => setReservations((prev) => prev.map((x) => x._id === r._id ? { ...x, status: 'CANCELLED' } : x)))}>Cancel</button> : null}</td></tr>)}</tbody></table></div> : <div className="empty-inline"><p>You don’t have any requests yet.</p><Link to="/search">Search for medicine <ArrowRight size={15}/></Link></div>}</Card><Card className="dashboard-side"><span className="side-icon"><ShieldCheck/></span><h3>A quick reminder</h3><Link to="/saved-pharmacies">Saved pharmacies</Link><p><Link to="/profile">Profile and saved locations</Link></p><p>Availability can change. Call the pharmacy to confirm before you make the trip.</p><Link to="/search">Find a pharmacy <ArrowRight size={15}/></Link></Card></div><RecentSearches/></div>; }

export function SavedPharmaciesPage() { const [saved, setSaved] = useState<any[]>([]); const [error, setError] = useState(''); async function load() { try { const { data } = await api.get('/saved-pharmacies'); setSaved(data.data.saved); } catch (e) { setError(errorMessage(e)); } } useEffect(() => { void load(); }, []); async function remove(id: string) { try { await api.delete(`/saved-pharmacies/${id}`); setSaved((prev) => prev.filter((entry) => String(entry.pharmacyId?._id) !== id)); } catch (e) { setError(errorMessage(e)); } } return <div className="container page-section"><div className="page-intro"><div className="eyebrow">YOUR MEDFIND</div><h1>Saved pharmacies</h1><p>Keep nearby participating pharmacies close at hand.</p></div>{error && <div className="inline-error">{error}</div>}{saved.length ? <div className="saved-pharmacy-grid">{saved.map((entry) => { const pharmacy = entry.pharmacyId; return <Card className="saved-pharmacy-card" key={entry._id}><span className="pharmacy-small-icon"><Store size={17}/></span><h3>{pharmacy?.name}</h3><p>{pharmacy?.address}, {pharmacy?.city} · {pharmacy?.pinCode}</p>{pharmacy?.phone && <a href={`tel:${pharmacy.phone}`}>Call pharmacy</a>}<button className="table-action" onClick={() => void remove(String(pharmacy?._id))}>Remove saved pharmacy</button></Card>; })}</div> : <Card className="empty-state"><h3>No saved pharmacies</h3><p>Save a participating pharmacy from its availability card.</p><Link className="button" to="/search">Find a pharmacy</Link></Card>}</div>; }

export function PharmacyDashboard() {
  const { user } = useAuth(); const [assignments, setAssignments] = useState<any[]>([]); const [loaded, setLoaded] = useState(false); const [pharmacies, setPharmacies] = useState<any[]>([]); const [selected, setSelected] = useState(''); const [inventory, setInventory] = useState<any[]>([]); const [reservations, setReservations] = useState<any[]>([]); const [medicineText, setMedicineText] = useState(''); const [error, setError] = useState(''); const [busy, setBusy] = useState(false); const [form, setForm] = useState({ medicineId: '', batchNumber: '', expiryDate: '', quantity: '10', sellingPrice: '', mrp: '' });
  const [inventoryPage, setInventoryPage] = useState(1); const [inventoryTotal, setInventoryTotal] = useState(0); const [inventoryLoading, setInventoryLoading] = useState(false);
  const [inventoryFilters, setInventoryFilters] = useState({ q: '', stockStatus: '', freshness: '', sort: 'updated_desc' });
  const currentPharmacy = useRef(selected); currentPharmacy.current = selected;
  const access = assignments.find((a) => a.pharmacyId === selected)?.capabilities || {};
  const pharmacy = pharmacies.find((p) => p._id === selected);
  const canWrite = Boolean(access.updateInventory && pharmacy?.verificationStatus === 'APPROVED' && pharmacy?.active);
  async function refreshInventory() { const pharmacyId = selected; const response = await api.get('/inventory', { params: { pharmacyId, page: inventoryPage, ...inventoryFilters } }); if (currentPharmacy.current === pharmacyId) { setInventory(response.data.data.inventory); setInventoryTotal(response.data.data.total); } }
  async function load() { try { const ph = await api.get('/pharmacies/mine'); const list = ph.data.data.pharmacies; setPharmacies(list); setAssignments(ph.data.data.assignments); if (!selected && list[0]) setSelected(list[0]._id); } catch (e) { setError(errorMessage(e)); } finally { setLoaded(true); } }
  useEffect(() => { void load(); }, []);
  useEffect(() => {
    let current = true; setInventory([]); setReservations([]); setError('');
    const permission = assignments.find((a) => a.pharmacyId === selected)?.capabilities;
    setInventoryTotal(0); setInventoryLoading(Boolean(selected && permission?.readInventory));
    if (selected && permission?.readInventory) api.get('/inventory', { params: { pharmacyId: selected, page: inventoryPage, ...inventoryFilters } }).then((r) => { if (current) { setInventory(r.data.data.inventory); setInventoryTotal(r.data.data.total); } }).catch((e) => { if (current) setError(errorMessage(e)); }).finally(() => { if (current) setInventoryLoading(false); });
    if (selected && permission?.readReservations) api.get('/reservations', { params: { pharmacyId: selected } }).then((r) => { if (current) setReservations(r.data.data.reservations); }).catch((e) => { if (current) setError(errorMessage(e)); });
    return () => { current = false; };
  }, [selected, assignments, inventoryPage, inventoryFilters]);
  async function addStock(e: FormEvent) { e.preventDefault(); if (!form.medicineId) { setError('Select an exact catalogue medicine first.'); return; } setBusy(true); setError(''); try { await api.post('/inventory/batches', { pharmacyId: selected, ...form, quantity: Number(form.quantity), sellingPrice: Number(form.sellingPrice), mrp: Number(form.mrp), expiryDate: new Date(form.expiryDate).toISOString() }); setForm({ medicineId: '', batchNumber: '', expiryDate: '', quantity: '10', sellingPrice: '', mrp: '' }); setMedicineText(''); await refreshInventory(); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  async function changeStatus(id: string, status: string) { try { await api.patch(`/reservations/${id}/status`, { status }); setReservations((prev) => prev.map((r) => r._id === id ? { ...r, status } : r)); } catch (e) { setError(errorMessage(e)); } }
  return <div className="container page-section"><div className="dashboard-welcome"><div><div className="eyebrow">PHARMACY WORKSPACE</div><h1>Pharmacy operations</h1><p>Manage stock and respond to reservation requests.</p></div>{pharmacies.length > 1 && <label className="filter-select">Pharmacy <select value={selected} onChange={(e) => { setInventoryPage(1); setSelected(e.target.value); }}>{pharmacies.map((p) => <option key={p._id} value={p._id}>{p.name}</option>)}</select></label>}</div>{error && <div className="inline-error">{error}</div>}{!loaded ? <Loading/> : !pharmacies.length && user?.roles.includes('PHARMACY_OWNER') ? <PharmacyOnboarding onCreated={(p) => { setPharmacies([p]); setSelected(p._id); void load(); }}/>: !pharmacies.length ? <Card><h2>No active pharmacy assignment</h2><p>Ask a pharmacy owner to add your account to their team.</p></Card> : null}{selected && <div className="status-banner"><ShieldCheck size={19}/><span><b>{pharmacies.find((p) => p._id === selected)?.name}</b> · Application status: {pharmacies.find((p) => p._id === selected)?.verificationStatus?.replaceAll('_', ' ')}</span></div>}{selected && <>{access.manageProfile && <PharmacyHoursForm key={selected} pharmacy={pharmacies.find((p) => p._id === selected)}/>}<div className="dashboard-grid"><Card className="dashboard-card"><div className="card-heading"><div><div className="eyebrow">STOCK MANAGEMENT</div><h2>Inventory batches</h2></div>{access.readReports && <a className="button button-outline button-small" href={`${import.meta.env.VITE_API_URL || 'http://localhost:4000/api/v1'}/reports/inventory.csv?pharmacyId=${selected}`} target="_blank" rel="noreferrer">Export CSV</a>}{access.readReports && <a className="button button-outline button-small" href={`${import.meta.env.VITE_API_URL || 'http://localhost:4000/api/v1'}/reports/inventory.xlsx?pharmacyId=${selected}`} target="_blank" rel="noreferrer">Export Excel</a>}</div>{access.updateInventory && !canWrite && <p className="team-note">Inventory changes are available after this pharmacy is approved and active.</p>}{canWrite && <><div className="inventory-add"><h3>Add a batch</h3><form className="inventory-form" onSubmit={addStock}><div className="field"><span>Catalogue medicine</span><MedicineAutocomplete value={medicineText} selectedId={form.medicineId || undefined} onChange={(value) => { setMedicineText(value); setForm((current) => ({ ...current, medicineId: '' })); }} onSelect={(medicine) => { setMedicineText(medicine.name); setForm((current) => ({ ...current, medicineId: medicine._id })); }}/><small>Select the exact catalogue identity before adding stock.</small></div><Field label="Batch number" required value={form.batchNumber} onChange={(e) => setForm({ ...form, batchNumber: e.target.value })}/><Field label="Expiry date" type="date" required value={form.expiryDate} onChange={(e) => setForm({ ...form, expiryDate: e.target.value })}/><Field label="Quantity" type="number" min="1" required value={form.quantity} onChange={(e) => setForm({ ...form, quantity: e.target.value })}/><Field label="Selling price (₹)" type="number" min="0" step="0.01" required value={form.sellingPrice} onChange={(e) => setForm({ ...form, sellingPrice: e.target.value })}/><Field label="MRP (₹)" type="number" min="0" step="0.01" required value={form.mrp} onChange={(e) => setForm({ ...form, mrp: e.target.value })}/><Button disabled={busy || !selected}>{busy ? 'Saving…' : 'Add stock'}</Button></form><small>All quantities are recorded by batch so expired items can be excluded and reservations can be allocated by expiry.</small></div><InventoryImportPanel key={selected} pharmacyId={selected} onComplete={() => { void refreshInventory().catch((e) => setError(errorMessage(e))); }}/></>}<InventoryFilterBar key={selected} initial={inventoryFilters} onApply={(next) => { setInventoryPage(1); setInventoryFilters(next); }}/>{inventory.length ? <><div className="table-wrap"><table><thead><tr><th>Medicine</th><th>Available</th><th>Last updated</th><th>Freshness</th><th></th></tr></thead><tbody>{inventory.map((i) => <tr key={i._id}><td>{i.medicineId?.name} <small>{i.medicineId?.strength}</small></td><td>{i.availableQuantity}</td><td>{age(i.lastUpdatedAt)}</td><td><StatusPill tone={i.freshness === 'RECENTLY_UPDATED' ? 'good' : 'warn'}>{i.freshness?.replaceAll('_', ' ') || 'UNKNOWN'}</StatusPill></td><td>{canWrite && <button className="table-action" onClick={() => void api.patch(`/inventory/${i._id}/status`, { stockStatus: i.stockStatus === 'AVAILABLE' ? 'UNAVAILABLE' : 'AVAILABLE' }).then(() => refreshInventory()).catch((e) => setError(errorMessage(e)))}>{i.stockStatus === 'AVAILABLE' ? 'Mark unavailable' : 'Mark available'}</button>}</td></tr>)}</tbody></table></div>{inventory.map((item) => <InventoryBatchManager key={item._id} item={item} canWrite={canWrite} refresh={refreshInventory}/>)}</> : <div className="empty-inline"><p>{access.readInventory ? 'No inventory batches yet.' : 'Inventory access has not been assigned to your account.'}</p></div>}{access.readInventory && <div className="support-pagination"><Button type="button" className="button-outline button-small" disabled={inventoryLoading || inventoryPage <= 1} onClick={() => setInventoryPage((value) => value - 1)}>Previous inventory page</Button><span>Page {inventoryPage} · {inventoryTotal} items</span><Button type="button" className="button-outline button-small" disabled={inventoryLoading || inventoryPage * 25 >= inventoryTotal} onClick={() => setInventoryPage((value) => value + 1)}>Next inventory page</Button></div>}{access.readInventory && <InventoryMovementHistory key={selected} pharmacyId={selected}/>}</Card><Card className="dashboard-side"><span className="side-icon"><Clock3/></span><h3>Reservation requests</h3>{reservations.map((r) => <div className="reservation-row" key={r._id}><b>{r.medicineId?.name || 'Medicine'} × {r.quantity}</b><small>{r.status} · {age(r.createdAt)}</small>{access.manageReservations && r.status === 'PENDING' && <div className="reservation-actions"><button onClick={() => void changeStatus(r._id, 'CONFIRMED')}>Confirm</button><button onClick={() => void changeStatus(r._id, 'REJECTED')}>Reject</button></div>}{access.manageReservations && r.status === 'CONFIRMED' && <button className="table-action" onClick={() => void changeStatus(r._id, 'READY_FOR_PICKUP')}>Mark ready</button>}{access.manageReservations && r.status === 'READY_FOR_PICKUP' && <button className="table-action" onClick={() => void changeStatus(r._id, 'COLLECTED')}>Mark collected</button>}</div>)}{reservations.length === 0 && <p>{access.readReservations ? 'No incoming requests yet.' : 'Reservation access has not been assigned to your account.'}</p>}</Card></div></>}</div>;
}

function InventoryFilterBar({ initial, onApply }: { initial: { q: string; stockStatus: string; freshness: string; sort: string }; onApply: (value: { q: string; stockStatus: string; freshness: string; sort: string }) => void }) {
  const [q, setQ] = useState(initial.q); const [stockStatus, setStockStatus] = useState(initial.stockStatus); const [freshness, setFreshness] = useState(initial.freshness); const [sort, setSort] = useState(initial.sort);
  function submit(event: FormEvent) { event.preventDefault(); onApply({ q: q.trim(), stockStatus, freshness, sort }); }
  return <form className="report-filters" onSubmit={submit}><Field label="Search inventory" maxLength={100} placeholder="Medicine, strength, form or manufacturer" value={q} onChange={(event) => setQ(event.target.value)}/><label className="field"><span>Stock status</span><select value={stockStatus} onChange={(event) => setStockStatus(event.target.value)}><option value="">All stock states</option><option value="AVAILABLE">Available</option><option value="UNAVAILABLE">Unavailable</option></select></label><label className="field"><span>Freshness</span><select value={freshness} onChange={(event) => setFreshness(event.target.value)}><option value="">All freshness states</option>{['RECENTLY_UPDATED','NEEDS_CONFIRMATION','STALE_WARNING','UNAVAILABLE_FOR_CONFIRMED_SEARCH'].map((value) => <option key={value} value={value}>{value.replaceAll('_', ' ')}</option>)}</select></label><label className="field"><span>Sort</span><select value={sort} onChange={(event) => setSort(event.target.value)}><option value="updated_desc">Recently updated</option><option value="updated_asc">Oldest updated</option></select></label><Button type="submit">Apply inventory filters</Button></form>;
}

function InventoryImportPanel({ pharmacyId, onComplete }: { pharmacyId: string; onComplete: () => void }) {
  const [file, setFile] = useState<File | null>(null); const [preview, setPreview] = useState<any>(null); const [error, setError] = useState(''); const [busy, setBusy] = useState(false);
  async function prepare(e: FormEvent) { e.preventDefault(); if (!file) return; setBusy(true); setError(''); setPreview(null); try { const body = new FormData(); body.append('file', file); body.append('pharmacyId', pharmacyId); const { data } = await api.post('/inventory/import/preview', body, { headers: { 'Content-Type': 'multipart/form-data' } }); setPreview(data.data); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  async function confirm() { if (!preview?.jobId) return; setBusy(true); setError(''); try { const { data } = await api.post(`/inventory/import/${preview.jobId}/confirm`, { confirm: true }); setPreview({ ...preview, committed: true, ...data.data }); onComplete(); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  return <section className="inventory-add"><h3>Import inventory CSV or Excel</h3><p className="import-hint">Required columns: medicineId, batchNumber, expiryDate, quantity, sellingPrice, mrp. Use dates in YYYY-MM-DD format and enter medicine IDs and batch numbers as text. Preview errors before confirming.</p><a className="text-link csv-template-link" href="/inventory-import-template.csv" download>Download CSV template <ArrowRight size={13}/></a> <a className="text-link csv-template-link" href={`${import.meta.env.VITE_API_URL || 'http://localhost:4000/api/v1'}/inventory/import/template.xlsx`} download>Download Excel template <ArrowRight size={13}/></a><form className="import-form" onSubmit={prepare}><input type="file" accept=".csv,.xlsx,text/csv,application/vnd.openxmlformats-officedocument.spreadsheetml.sheet" required onChange={(e) => { setFile(e.target.files?.[0] || null); setPreview(null); }}/><Button disabled={busy || !file}>{busy ? 'Reviewing…' : 'Upload and preview'}</Button></form>{error && <div className="inline-error">{error}</div>}{preview && <div className="import-preview"><div className="import-summary"><b>{preview.validRows ?? preview.importedRows} valid rows</b><span>{preview.invalidRows ?? preview.rejectedRows} row errors</span></div>{preview.errors?.length > 0 && <div className="import-errors" role="region" aria-label="Import row errors">{preview.errors.map((row: any) => <p key={`${row.rowNumber}-${row.message}`}><b>Row {row.rowNumber}:</b> {row.message}</p>)}</div>}{preview.rowErrors?.length > 0 && <div className="import-errors">{preview.rowErrors.map((row: any) => <p key={`${row.rowNumber}-${row.message}`}><b>Row {row.rowNumber}:</b> {row.message}</p>)}</div>}{preview.committed ? <div className="inline-success">Import complete. {preview.importedRows} rows imported; {preview.rejectedRows} invalid rows skipped.</div> : preview.validRows > 0 ? <Button disabled={busy} onClick={() => void confirm()}>Confirm import of {preview.validRows} valid rows{preview.invalidRows ? ` (skip ${preview.invalidRows} errors)` : ''}</Button> : null}</div>}</section>;
}

function PharmacyOnboarding({ onCreated }: { onCreated: (pharmacy: any) => void }) {
  const [busy, setBusy] = useState(false); const [error, setError] = useState(''); const [document, setDocument] = useState<File | null>(null); const [draft, setDraft] = useState<any>(null);
  const [form, setForm] = useState({ name: '', address: '', pinCode: '', city: 'Hyderabad', state: 'Telangana', latitude: '', longitude: '', phone: '', email: '', licenseNumber: '', registeredPharmacistName: '' });
  async function submit(e: FormEvent) { e.preventDefault(); setBusy(true); setError(''); try { let pharmacy = draft; if (!pharmacy) { const { data } = await api.post('/pharmacies', { name: form.name, address: form.address, pinCode: form.pinCode, city: form.city, state: form.state, coordinates: [Number(form.longitude), Number(form.latitude)], phone: form.phone || undefined, email: form.email || undefined, licenseNumber: form.licenseNumber, registeredPharmacistName: form.registeredPharmacistName, openingHours: [] }); pharmacy = data.data.pharmacy; setDraft(pharmacy); } if (document) { const body = new FormData(); body.append('document', document); await api.post(`/pharmacies/${pharmacy._id}/license-document`, body, { headers: { 'Content-Type': 'multipart/form-data' } }); } await api.patch(`/pharmacies/${pharmacy._id}/submit`, {}); onCreated(pharmacy); } catch (e) { setError(errorMessage(e)); } finally { setBusy(false); } }
  return <Card className="onboarding-card"><div className="eyebrow">PHARMACY ONBOARDING</div><h2>Register your pharmacy</h2><p>Submit your location and licence details to begin verification. Your pharmacy appears in public discovery only after approval.</p><form className="onboarding-form" onSubmit={submit}><Field label="Pharmacy name" required value={form.name} onChange={(e) => setForm({ ...form, name: e.target.value })}/><Field label="Owner contact email" type="email" required value={form.email} onChange={(e) => setForm({ ...form, email: e.target.value })}/><Field label="Phone" value={form.phone} onChange={(e) => setForm({ ...form, phone: e.target.value })}/><Field label="Drug licence number" required value={form.licenseNumber} onChange={(e) => setForm({ ...form, licenseNumber: e.target.value })}/><Field label="Registered pharmacist name" required value={form.registeredPharmacistName} onChange={(e) => setForm({ ...form, registeredPharmacistName: e.target.value })}/><Field label="Street address" required value={form.address} onChange={(e) => setForm({ ...form, address: e.target.value })}/><Field label="PIN code" required pattern="[0-9]{6}" maxLength={6} value={form.pinCode} onChange={(e) => setForm({ ...form, pinCode: e.target.value })}/><Field label="City" required value={form.city} onChange={(e) => setForm({ ...form, city: e.target.value })}/><Field label="State" required value={form.state} onChange={(e) => setForm({ ...form, state: e.target.value })}/><Field label="Latitude" type="number" min="-90" max="90" step="any" required value={form.latitude} onChange={(e) => setForm({ ...form, latitude: e.target.value })}/><Field label="Longitude" type="number" min="-180" max="180" step="any" required value={form.longitude} onChange={(e) => setForm({ ...form, longitude: e.target.value })}/>{!draft && <label className="field"><span>Drug licence document (PDF, JPG or PNG)</span><input type="file" accept="application/pdf,image/jpeg,image/png" required onChange={(e) => setDocument(e.target.files?.[0] || null)}/><small>Stored privately. Only authorized verification staff can open it.</small></label>}{draft && <label className="field"><span>Drug licence document (PDF, JPG or PNG)</span><input type="file" accept="application/pdf,image/jpeg,image/png" onChange={(e) => setDocument(e.target.files?.[0] || null)}/><small>Continue your saved draft. Choose the licence document to finish submission.</small></label>}{error && <div className="inline-error">{error}</div>}<Button disabled={busy}>{busy ? 'Submitting…' : draft ? 'Upload and submit application' : 'Create profile and upload licence'}</Button></form></Card>;
}

export function AdminDashboard() { const { user } = useAuth(); const can = (permission: string) => Boolean(user?.permissions?.includes('*') || user?.permissions?.includes(permission)); const [metrics, setMetrics] = useState<any>(); const [pendingCount, setPendingCount] = useState(0); const [tab, setTab] = useState('overview'); const [error, setError] = useState(''); async function load() { setError(''); const requests = [can('report:read') ? api.get('/admin/overview').then((r) => setMetrics(r.data.data)) : Promise.resolve(), can('pharmacy:review') ? Promise.all([api.get('/admin/pharmacies', { params: { status: 'SUBMITTED', limit: 1 } }), api.get('/admin/pharmacies', { params: { status: 'UNDER_REVIEW', limit: 1 } })]).then(([submitted, review]) => setPendingCount(submitted.data.data.total + review.data.data.total)) : Promise.resolve()]; const results = await Promise.allSettled(requests); const failure = results.find((result) => result.status === 'rejected'); if (failure?.status === 'rejected') setError(errorMessage(failure.reason)); } useEffect(() => { void load(); }, [user?.permissions?.join(',')]);  return <div className="admin-layout"><aside className="admin-sidebar"><div className="eyebrow">PLATFORM</div><h3>Operations</h3>{['overview', 'pharmacies', 'users'].map((t) => <button className={tab === t ? 'admin-nav-active' : ''} key={t} onClick={() => setTab(t)}>{t === 'overview' ? <ShieldCheck size={16}/> : t === 'pharmacies' ? <Store size={16}/> : <Users size={16}/>}<span>{t[0]!.toUpperCase() + t.slice(1)}</span>{t === 'pharmacies' && <b>{pendingCount}</b>}</button>)}</aside><section className="admin-content"><div className="dashboard-welcome"><div><div className="eyebrow">MEDFIND ADMINISTRATION</div><h1>{tab === 'overview' ? 'Platform overview' : tab === 'pharmacies' ? 'Pharmacy verification' : 'User directory'}</h1></div></div>{error && <div className="inline-error">{error}</div>}{tab === 'overview' && !can('report:read') && <Card><p>Your current policy does not allow the platform overview. Choose an authorized workspace from the navigation.</p></Card>}{tab === 'overview' && can('report:read') && <><div className="metrics-grid">{[['Total users', metrics?.users], ['Customers', metrics?.customers], ['Verified pharmacies', metrics?.verifiedPharmacies], ['Pending reviews', metrics?.pendingApprovals], ['Active pharmacies', metrics?.activePharmacies], ['Medicine catalogue', metrics?.medicines], ['Reservation requests', metrics?.reservations], ['Collected reservations', metrics?.completedReservations]].map(([label, value]) => <Card className="metric-card" key={label}><span>{label}</span><b>{value ?? '—'}</b><small>Platform total</small></Card>)}</div><Card><h2>Recent operational activity</h2><p>{metrics?.inventoryUpdatesLast24h ?? '—'} inventory updates in the last 24 hours.</p></Card></>}{tab === 'pharmacies' && !can('pharmacy:review') && <Card><p>Your current policy does not allow pharmacy reviews.</p></Card>}{tab === 'pharmacies' && can('pharmacy:review') && <Card><h2>Pharmacy applications and activity</h2><p>Search all pharmacies, review private evidence and inspect inventory and reservations.</p><Link className="button" to="/admin/pharmacies">Manage pharmacies</Link></Card>}{tab === 'users' && <Card><h2>User directory and access</h2><p>Search accounts and review access changes with a reason and current revision.</p><Link className="button" to="/admin/users">Manage user access</Link></Card>}</section></div>; }

export function AdminSettingsPage() { const [value, setValue] = useState<any>(null); const [message, setMessage] = useState(''); const [error, setError] = useState(''); async function load() { try { const { data } = await api.get('/admin/settings'); setValue(data.data); } catch (e) { setError(errorMessage(e)); } } useEffect(() => { void load(); }, []); function update(group: string, key: string, raw: string) { setValue((current: any) => ({ ...current, [group]: { ...current[group], [key]: Number(raw) } })); } async function save(e: FormEvent) { e.preventDefault(); setError(''); setMessage(''); try { await api.patch('/admin/settings', value); setMessage('Platform thresholds saved.'); } catch (e) { setError(errorMessage(e)); } } if (!value) return <div className="container page-section">{error ? <div className="inline-error">{error}</div> : <Loading/>}</div>; return <div className="container page-section narrow-page"><div className="page-intro"><div className="eyebrow">SUPER ADMIN</div><h1>Platform settings</h1><p>Configure freshness labels and reservation hold/pickup windows.</p></div><Card className="dashboard-card"><form className="form-stack" onSubmit={save}><h2>Inventory freshness (minutes)</h2><div className="settings-grid"><Field label="Recently updated through" type="number" min="1" value={value.inventoryFreshness.recentMinutes} onChange={(e) => update('inventoryFreshness', 'recentMinutes', e.target.value)}/><Field label="Needs confirmation through" type="number" min="1" value={value.inventoryFreshness.confirmMinutes} onChange={(e) => update('inventoryFreshness', 'confirmMinutes', e.target.value)}/><Field label="Stale warning through" type="number" min="1" value={value.inventoryFreshness.staleMinutes} onChange={(e) => update('inventoryFreshness', 'staleMinutes', e.target.value)}/></div><h2>Reservation windows</h2><div className="settings-grid"><Field label="Pending hold (minutes)" type="number" min="1" value={value.reservations.holdMinutes} onChange={(e) => update('reservations', 'holdMinutes', e.target.value)}/><Field label="Pickup deadline (hours)" type="number" min="1" value={value.reservations.pickupDeadlineHours} onChange={(e) => update('reservations', 'pickupDeadlineHours', e.target.value)}/></div>{error && <div className="inline-error">{error}</div>}{message && <div className="inline-success">{message}</div>}<Button>Save platform settings</Button></form></Card></div>; }




export function StaticPage({ type }: { type: 'about' | 'privacy' | 'terms' }) { const content = { about: ['About MedFind', 'MedFind helps people discover nearby participating pharmacies reporting medicine availability. Pharmacies manage their own stock data; customers contact pharmacies directly to confirm.'], privacy: ['Privacy policy', 'MedFind uses account details to provide search, reservation request and support features. Location is optional and is used to find nearby pharmacies when you choose to share it. We do not ask customers to upload prescriptions.'], terms: ['Terms and conditions', 'MedFind provides medicine availability discovery. It is not an online pharmacy, seller, prescriber or delivery service. All dispensing, prescription verification, pricing confirmation and regulated transactions are handled by licensed pharmacies and authorized professionals.'] }[type]; return <div className="container page-section narrow-page"><div className="page-intro"><div className="eyebrow">MEDFIND</div><h1>{content[0]}</h1></div><Card className="prose-card"><p>{content[1]}</p><h3>Availability information</h3><p>Inventory information comes from participating pharmacies and can become outdated. Freshness labels show when availability was last reported. Please contact the pharmacy to confirm before travelling.</p><h3>Professional decisions</h3><p>MedFind does not recommend medicine substitutions or authorize dispensing. Pharmacy professionals are responsible for decisions within their regulated practice.</p><Link to="/search" className="text-link">Search nearby pharmacies <ArrowRight size={16}/></Link></Card></div>; }

export function ContactPage() {
  const { user } = useAuth();
  return <div className="container page-section narrow-page"><div className="page-intro"><div className="eyebrow">MEDFIND</div><h1>Contact</h1><p>Choose the right place to reach the MedFind team.</p></div><Card className="prose-card"><h3>Customer or pharmacy support</h3><p>Sign in to create a private support ticket and follow replies from your account. For medicine availability, contact the pharmacy shown in search results directly.</p><Link className="button" to={user ? '/support' : '/login'}>{user ? 'Open support' : 'Sign in for support'}</Link><h3>Joining as a pharmacy</h3><p>Pharmacy owners can create an account and submit their pharmacy profile for review.</p><Link className="text-link" to="/register">Create an account <ArrowRight size={16}/></Link><h3>Platform details</h3><p>MedFind does not provide medical advice, sell medicines or arrange delivery. Use the support area for account or platform issues.</p></Card></div>;
}
